oken']) ?>"><label>כתובת משלוח<textarea name="address" minlength="5" maxlength="160" required placeholder="עיר, רחוב ומספר בית"></textarea></label><button class="button dark">יצירת הזמנת הדגמה ←</button></form><?php endif ?></aside></div><?php endif ?>
